import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load the sprite texture
  const textureMap = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with aspect ratio from atlas region (512:320 = 1.6:1)
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1);

  // Create material using TSL nodes
  const textureNode = texture(textureMap);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true
  });

  // Create and add mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Setup cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Setup handlers object (no event handlers needed for static sprite)
  group.userData.handlers = {};

  return group;
}
